/**
 * Load, inspect, validate, and use X.509 certificates throughout Chilkat.
 *
 * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html
 */
class Cert
{
    /** When true (the default), a failed call throws Chilkat2\Exception instead of returning false or null. Inherited by objects this object returns. */
    public bool $RaiseError;

    /**
     * If set to a file path, this property logs the LastErrorText of each Chilkat method or property call to the specified file.
     */
    public string $DebugLogFilePath;

    /**
     * Provides HTML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorHtml;

    /**
     * Provides plain text information about the last called method or property.
     */
    public readonly string $LastErrorText;

    /**
     * Provides XML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorXml;

    /**
     * Indicates the success or failure of the most recent method call: `true` means success, `false` means failure.
     */
    public bool $LastMethodSuccess;

    /**
     * If set to `true`, then the contents of LastErrorText (or LastErrorXml, or LastErrorHtml) may contain more verbose information.
     */
    public bool $VerboseLogging;

    /**
     * Version of the component/library, such as "10.1.0"
     */
    public readonly string $Version;

    /**
     * The authority key identifier of the certificate in base64 string format.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#AuthorityKeyId
     */
    public readonly string $AuthorityKeyId;

    /**
     * Applies only when running on a Microsoft Windows operating system.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#AvoidWindowsPkAccess
     */
    public bool $AvoidWindowsPkAccess;

    /**
     * The version of the certificate (1, 2, or 3).
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#CertVersion
     */
    public readonly int $CertVersion;

    /**
     * Has a value of `true` if the certificate or any certificate in the chain of authority has expired.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#Expired
     */
    public readonly bool $Expired;

    /**
     * Returns a string containing a comma separated list of keywords with the extended key usages of the certificate.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ExtendedKeyUsage
     */
    public readonly string $ExtendedKeyUsage;

    /**
     * `true` if this certificate can be used for client authentication, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ForClientAuthentication
     */
    public readonly bool $ForClientAuthentication;

    /**
     * `true` if this certificate can be used for code signing, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ForCodeSigning
     */
    public readonly bool $ForCodeSigning;

    /**
     * `true` if this certificate can be used for sending secure email, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ForSecureEmail
     */
    public readonly bool $ForSecureEmail;

    /**
     * `true` if this certificate can be used for server authentication, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ForServerAuthentication
     */
    public readonly bool $ForServerAuthentication;

    /**
     * `true` if this certificate can be used for time stamping, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#ForTimeStamping
     */
    public readonly bool $ForTimeStamping;

    /**
     * Bitflags indicating the intended usages of the certificate.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IntendedKeyUsage
     */
    public readonly int $IntendedKeyUsage;

    /**
     * `true` if this is the root certificate, otherwise `false`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IsRoot
     */
    public readonly bool $IsRoot;

    /**
     * The certificate issuer's country.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IssuerC
     */
    public readonly string $IssuerC;

    /**
     * The certificate issuer's common name.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IssuerCN
     */
    public readonly string $IssuerCN;

    /**
     * The issuer's full distinguished name.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IssuerDN
     */
    public readonly string $IssuerDN;

    /**
     * The certificate issuer's email address.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2CertRef.html#IssuerE
     */
