/**
 * Generate, parse, and verify NTLM authentication messages.
 *
 * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html
 */
class Ntlm
{
    /** When true (the default), a failed call throws Chilkat2\Exception instead of returning false or null. Inherited by objects this object returns. */
    public bool $RaiseError;

    /**
     * If set to a file path, this property logs the LastErrorText of each Chilkat method or property call to the specified file.
     */
    public string $DebugLogFilePath;

    /**
     * Provides HTML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorHtml;

    /**
     * Provides plain text information about the last called method or property.
     */
    public readonly string $LastErrorText;

    /**
     * Provides XML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorXml;

    /**
     * Indicates the success or failure of the most recent method call: `true` means success, `false` means failure.
     */
    public bool $LastMethodSuccess;

    /**
     * If set to `true`, then the contents of LastErrorText (or LastErrorXml, or LastErrorHtml) may contain more verbose information.
     */
    public bool $VerboseLogging;

    /**
     * Version of the component/library, such as "10.1.0"
     */
    public readonly string $Version;

    /**
     * Specifies the 8-byte client challenge used when generating the Type 3 authenticate message.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#ClientChallenge
     */
    public string $ClientChallenge;

    /**
     * Specifies the server's DNS computer name for inclusion in the `MsvAvDnsComputerName` entry of the Type 2 message's `TargetInfo` block.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#DnsComputerName
     */
    public string $DnsComputerName;

    /**
     * Specifies the server's DNS domain name for inclusion in the `MsvAvDnsDomainName` entry of the Type 2 message's `TargetInfo` block.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#DnsDomainName
     */
    public string $DnsDomainName;

    /**
     * Specifies the client's domain or workgroup name.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#Domain
     */
    public string $Domain;

    /**
     * Controls the textual encoding used when Chilkat exposes binary NTLM values as strings or accepts them from strings.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#EncodingMode
     */
    public string $EncodingMode;

    /**
     * Specifies the NTLM negotiate flags as a compact string in which each letter represents one bit.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#Flags
     */
    public string $Flags;

    /**
     * Specifies the server's NetBIOS computer name for inclusion in the `MsvAvNbComputerName` entry of the Type 2 message's `TargetInfo` block.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#NetBiosComputerName
     */
    public string $NetBiosComputerName;

    /**
     * Specifies the server's NetBIOS domain name for inclusion in the `MsvAvNbDomainName` entry of the Type 2 message's `TargetInfo` block.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#NetBiosDomainName
     */
    public string $NetBiosDomainName;

    /**
     * Selects the challenge-response algorithm used to generate and verify the authentication response.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#NtlmVersion
     */
    public int $NtlmVersion;

    /**
     * Specifies the OEM code page used to encode NTLM text fields when Unicode negotiation is disabled.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#OemCodePage
     */
    public int $OemCodePage;

    /**
     * Specifies the password for `UserName`.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#Password
     */
    public string $Password;

    /**
     * Specifies the 8-byte server challenge carried in the Type 2 challenge message.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#ServerChallenge
     */
    public string $ServerChallenge;

    /**
     * Specifies the server-provided authentication target placed in the Type 2 challenge message.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#TargetName
     */
    public string $TargetName;

    /**
     * Specifies the account name to authenticate.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#UserName
     */
    public string $UserName;

    /**
     * Specifies the optional client workstation name.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2NtlmRef.html#Workstation
     */
    public string $Workstation;

    /**
     * Creates the object; the optional array sets properties ('ConnectTimeout' => 30, 'RaiseError' => false, ...).
     * @param array<string, mixed> $properties
     * @throws \Error for an unknown or read-only property name
     */
