/**
 * Collect certificates, certificate chains, PEM data, and PFX private keys in an XML vault.
 *
 * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html
 */
class XmlCertVault
{
    /** When true (the default), a failed call throws Chilkat2\Exception instead of returning false or null. Inherited by objects this object returns. */
    public bool $RaiseError;

    /**
     * If set to a file path, this property logs the LastErrorText of each Chilkat method or property call to the specified file.
     */
    public string $DebugLogFilePath;

    /**
     * Provides HTML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorHtml;

    /**
     * Provides plain text information about the last called method or property.
     */
    public readonly string $LastErrorText;

    /**
     * Provides XML-formatted information about the last called method or property.
     */
    public readonly string $LastErrorXml;

    /**
     * Indicates the success or failure of the most recent method call: `true` means success, `false` means failure.
     */
    public bool $LastMethodSuccess;

    /**
     * If set to `true`, then the contents of LastErrorText (or LastErrorXml, or LastErrorHtml) may contain more verbose information.
     */
    public bool $VerboseLogging;

    /**
     * Version of the component/library, such as "10.1.0"
     */
    public readonly string $Version;

    /**
     * The master password for the vault.
     *
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#MasterPassword
     */
    public string $MasterPassword;

    /**
     * Creates the object; the optional array sets properties ('ConnectTimeout' => 30, 'RaiseError' => false, ...).
     * @param array<string, mixed> $properties
     * @throws \Error for an unknown or read-only property name
     */
    public function __construct(array $properties = []) {}

    /**
     * Adds a certificate to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddCert
     */
    public function AddCert(Cert $cert): bool {}

    /**
     * Adds a chain of certificates to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddCertChain
     */
    public function AddCertChain(CertChain $certChain): bool {}

    /**
     * Adds a certificate to the XML vault where certificate is passed directly from encoded bytes (such as Base64, Hex, etc.).
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddCertEncoded
     */
    public function AddCertEncoded(string $encodedBytes, string $encoding): bool {}

    /**
     * Adds a certificate to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddCertFile
     */
    public function AddCertFile(string $path): bool {}

    /**
     * Adds a certificate from any string representation format such as PEM.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddCertString
     */
    public function AddCertString(string $certData): bool {}

    /**
     * Adds the contents of a PEM file to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddPemFile
     */
    public function AddPemFile(string $path, string $password): bool {}

    /**
     * Adds a PFX (PKCS12) to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddPfx
     */
    public function AddPfx(Pfx $pfx): bool {}

    /**
     * Adds a PFX to the XML vault where PFX is passed directly from encoded bytes (such as Base64, Hex, etc.).
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddPfxEncoded
     */
    public function AddPfxEncoded(string $encodedBytes, string $encoding, string $password): bool {}

    /**
     * Adds a PFX file to the XML vault.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#AddPfxFile
     */
    public function AddPfxFile(string $path, string $password): bool {}

    /**
     * Returns the contents of the cert vault as an XML string.
     *
     * @return string|null the result; on failure throws Chilkat2\Exception (RaiseError) or returns null
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#GetXml
     */
    public function GetXml(): ?string {}

    /**
     * Loads from an XML string.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#LoadXml
     */
    public function LoadXml(string $xml): bool {}

    /**
     * Loads from an XML file.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#LoadXmlFile
     */
    public function LoadXmlFile(string $path): bool {}

    /**
     * Saves the contents to an XML file.
     *
     * @return bool true on success; on failure throws Chilkat2\Exception (RaiseError) or returns false
     * @throws Exception
     * @see https://www.chilkatsoft.com/refdoc/php2XmlCertVaultRef.html#SaveXml
     */
    public function SaveXml(string $path): bool {}
}

